@@
 				);

+				if ( false === $result ) {
+					$write_failed = true;
+					break;
+				}
+
-				if ( $result !== false && $result > 0 ) {
+				if ( $result > 0 ) {
 					$reaped[] = $row->job_id;
 					ActiveJobFailureDiagnostic::log( $diagnostic, $row->session_id );
 				}
 			}
-		} while ( $row_count === self::STALE_REAP_BATCH_SIZE );
+		} while ( $row_count === self::STALE_REAP_BATCH_SIZE && ! $write_failed );
```
